@SpendingValidator
class BlsCheck {
    @Entrypoint
    static boolean validate(PlutusData redeemer, ScriptContext ctx) {
        byte[] msg = Builtins.integerToByteString(true, 4, 42);
        byte[] point = Builtins.bls12_381_G1_compress(Builtins.bls12_381_G1_hashToGroup(msg, msg));
        return Builtins.lengthOfByteString(point) == 48;
    }
}
